#!/usr/bin/env node
/**
 * @module scripts/backlog-set
 *
 * Set ownership / progress fields on one backlog story. Used by agent-start.sh / agent-teardown.sh and by agents
 * as they work (bump `progress` with every commit).
 *
 * BOARD.md is NOT regenerated by default (it would conflict across parallel
 * branches); pass --board on main, or run backlog-board.mjs after a merge.
 *
 * Usage:
 *   node scripts/backlog-set.mjs <story-id> key=value [key=value ...] [--board]
 *   node scripts/backlog-set.mjs SC-7.1 progress=40
 *   node scripts/backlog-set.mjs SC-7.1 owner="Build demo thread" model=claude-opus-5-5 status="In Progress"
 *
 * Allowed keys: owner, model, progress (0-100), status, branch, pr.
 */

import { resolve, dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { execFileSync } from "node:child_process";
import { STATUSES as STATUS_LIST, findTaskFile, updateTaskFile } from "./lib/backlog-frontmatter.mjs";

const ALLOWED = new Set(["owner", "model", "progress", "status", "branch", "pr"]);
const STATUSES = new Set(STATUS_LIST);

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const tasksDir = join(root, "backlog/tasks");
const [id, ...rest] = process.argv.slice(2);
if (!id) {
  console.error("usage: backlog-set.mjs <story-id> key=value ...");
  process.exit(2);
}
const path = findTaskFile(tasksDir, id);
if (!path) {
  console.error(`✗ no backlog file for ${id}`);
  process.exit(1);
}

const updates = {};
for (const arg of rest.filter((a) => !a.startsWith("--"))) {
  const eq = arg.indexOf("=");
  const key = arg.slice(0, eq);
  const value = arg.slice(eq + 1);
  if (eq < 1 || !ALLOWED.has(key)) {
    console.error(`✗ bad field "${arg}" (allowed: ${[...ALLOWED].join(", ")})`);
    process.exit(2);
  }
  if (key === "progress") {
    const n = Number(value);
    if (!Number.isInteger(n) || n < 0 || n > 100) {
      console.error("✗ progress must be an integer 0-100");
      process.exit(2);
    }
    updates.progress = n;
  } else if (key === "status" && !STATUSES.has(value)) {
    console.error(`✗ status must be one of: ${[...STATUSES].join(", ")}`);
    process.exit(2);
  } else updates[key] = value;
}
if (updates.status === "Done" && updates.progress === undefined) updates.progress = 100;
// Real clock, UTC: claims-status.mjs reads updated_date as liveness evidence.
const d = new Date();
const pad = (n) => String(n).padStart(2, "0");
updates.updated_date = `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())} ${pad(d.getUTCHours())}:${pad(d.getUTCMinutes())}`;

updateTaskFile(path, updates);
console.log(`✓ ${id}: ${Object.entries(updates).map(([k, v]) => `${k}=${v}`).join(" ")}`);

if (process.argv.includes("--board")) {
  execFileSync(process.execPath, [join(root, "scripts/backlog-board.mjs")], { stdio: "inherit" });
}
